{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 청년 기본 조례상 청년시설에 대해 서울시가 시설운영비와 활동비 전액을 반드시 지원해야 하는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 청년 기본 조례 제21조 제1항은 시장이 청년시설을 설치·운영 및 지원할 수 있고, 예산의 범위에서 시설운영 및 그 활동 등에 필요한 경비의 일부를 보조할 수 있다고 정하고 있습니다. 따라서 청년시설이라는 이유만으로 서울시가 시설운영비와 활동비 전액을 반드시 지원해야 한다고 볼 수는 없습니다.",
          "b_ids": "청년:제21조제1항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
